COUNTS = {"A_LOCAL": 34, "B_EXTERNA": 7, "C_DECLARATIVA": 4, "P_SIN_ASERCION": 5}


def normalized(text: str) -> str:
    """Compare the canonical clauses without Markdown decoration."""
    clean = re.sub(r"<[^>]*>", " ", text.lower())
    return " ".join(re.findall(r"[^\W_]+", clean, flags=re.UNICODE))


def matrix_rows(text: str) -> dict[str, tuple[str, str, str]]:
    """Read five-column inventory, rejecting collisions."""
    found = {}
    for line in text.splitlines():
        match = re.match(r"^\| (S\d+-R\d{3})\s*· ", line)
        if match is None:
            continue
        pieces = line.split(" | ")
        if len(pieces) != 5 or match[1] in found:
            raise ValueError("Duplicate or malformed inventory row " + match[1])
        found[match[1]] = (pieces[1].strip(), pieces[2].strip(), pieces[3].strip())
    return found


def report_rows(text: str) -> dict[str, list[str]]:
    """Never ignore a malformed or unregistered requirement row."""
    found = {}
    for line in text.splitlines():
        if not line.startswith("| " + TICK + "S"):
            continue
        parts = [item.strip() for item in line.strip().strip("|").split("|")]
        if len(parts) != 7 or not re.fullmatch(re.escape(TICK) + r"S\d+-R\d{3}" + re.escape(TICK), parts[0]):
            raise ValueError("Malformed report row")
        ident = parts[0].strip(TICK)
        if ident in found:
            raise ValueError("Duplicate report row " + ident)
        found[ident] = parts
    return found


def validate(matrix: str, spec: str, report: str, cases=CASES) -> int:
    """Ensure 50 rows remain unverified with real prior regression coverage."""
    ids = [case["id"] for case in cases]
    if len(ids) != 50 or len(set(ids)) != 50:
        raise ValueError("Exactly 50 unique requirements are mandatory")
    if {name: sum(case["category"] == name for case in cases) for name in COUNTS} != COUNTS:
        raise ValueError("Evidence classes drifted")
    if "NO_VERIFICABLE se conserva para las 50 filas" not in report:
        raise ValueError("Fail-closed verdict removed")
    if "0 promociones" not in report or "B_EXTERNA" not in report or "UNKNOWN" not in report:
        raise ValueError("Unproven operations were misrepresented")
    inventory, output, specification = matrix_rows(matrix), report_rows(report), normalized(spec)
    if set(output) != set(ids):
        raise ValueError("Report incomplete or contains invented rows")
    for case in cases:
        ident = case["id"]
        if inventory.get(ident) != (case["requirement"], "NO_VERIFICABLE", case["gap"]):
            raise ValueError("Canonical inventory or evidence drift " + ident)
        if normalized(case["requirement"]) not in specification:
            raise ValueError("Source SPEC changed " + ident)
        parts = case["witness"].split("::")
        if len(parts) != 3 or not parts[0].startswith("tests/test_cobertura_brvtal_"):
            raise ValueError("Untrusted witness " + ident)
        if not (ROOT / parts[0]).is_file():
            raise ValueError("Missing witness " + ident)
        suite = importlib.import_module(parts[0].replace("/", ".").removesuffix(".py"))
        method = getattr(getattr(suite, parts[1], None), parts[2], None)
        if not callable(method):
            raise ValueError("Witness method absent " + ident)
        observed = set(getattr(suite, "IDS", ()))
        for field in ("A", "B", "C"):
            observed.update(getattr(suite, field, ()))
        if ident not in observed:
            raise ValueError("Witness not bound to requirement " + ident)
        expected = [
            ident, case["category"], "NO_VERIFICABLE", case["requirement"],
            TICK + case["witness"] + TICK,
            "[PR #" + case["prior_pr"] + "](https://github.com/pl0n3r/brvtal/pull/"
            + case["prior_pr"] + ")", case["gap"],
        ]
        if output[ident] != expected:
            raise ValueError("Reported evidence drift " + ident)
    return len(output)


class VerificacionBrvtal04Tests(unittest.TestCase):
    """Actual regression suites plus reversible, negative proof checks."""

    def test_cincuenta_filas_y_fuentes_conservadas(self):
        """Every inventory requirement is present with unchanged evidence."""
        self.assertEqual(50, validate(
            MATRIX.read_text(encoding="utf-8"),
            SPEC.read_text(encoding="utf-8"),
            REPORT.read_text(encoding="utf-8"),
        ))

    def test_mutaciones_y_promociones_ficticias_fallan(self):
        """Missing, forged, duplicate or promoted clauses must fail closed."""
        matrix = MATRIX.read_text(encoding="utf-8")
        spec = SPEC.read_text(encoding="utf-8")
        report = REPORT.read_text(encoding="utf-8")
        case = CASES[0]
        row = next(line for line in report.splitlines()
                   if line.startswith("| " + TICK + case["id"] + TICK + " |"))
        source = next(line for line in matrix.splitlines()
                      if line.startswith("| " + case["id"] + " · "))
        mutations = [
            (matrix, spec, report.replace(row + "\n", "", 1)),
            (matrix, spec, report.replace(row, row + "\n" + row, 1)),
            (matrix, spec, report.replace(case["id"], "S99-R999", 1)),
            (matrix, spec, report.replace("NO_VERIFICABLE |", "CUBIERTO |", 1)),
            (matrix, spec, report.replace("A_LOCAL |", "C_DECLARATIVA |", 1)),
            (matrix, spec, report.replace("[PR #" + case["prior_pr"] + "]",
                                          "[PR #999999]", 1)),
            (matrix.replace(source, source.replace("NO_VERIFICABLE", "CUBIERTO"), 1),
             spec, report),
            (matrix, spec.replace("Site Settings centralizes global configuration.", "INVALID_CLAUSE", 1), report),
            (matrix, spec, report + "\n| " + TICK + "S99-R999" + TICK
             + " | A_LOCAL | NO_VERIFICABLE | invented | "
             + TICK + "tests/missing.py" + TICK
             + " | [PR #1](https://github.com) | not proven |\n"),
        ]
        for i, inputs in enumerate(mutations):
            with self.subTest(mutation=i), self.assertRaises(ValueError):
                validate(*inputs)

    def test_evidencia_externa_y_legal_no_equivale_a_green(self):
        """Operational and legal observations remain unaccredited."""
        self.assertEqual(COUNTS, {
            name: sum(case["category"] == name for case in CASES) for name in COUNTS
        })
        categories = {case["id"]: case["category"] for case in CASES}
        self.assertEqual("B_EXTERNA", categories["S33-R001"])
        self.assertEqual("P_SIN_ASERCION", categories["S31-R002"])
        report = REPORT.read_text(encoding="utf-8")
        self.assertIn("0 promociones", report)
        self.assertIn("UNKNOWN", report)
        self.assertNotIn("VALIDATED_IN_PRODUCTION", report)

    def test_regresiones_de_codigo_con_fixtures_sinteticos(self):
        """Exercise prior PHP and JS behavior rather than scanning for text."""
        result = subprocess.run(
            [sys.executable, "-m", "unittest", "-q",
             "tests.test_cobertura_brvtal_10", "tests.test_cobertura_brvtal_11",
             "tests.test_cobertura_brvtal_12"],
            cwd=ROOT, text=True, capture_output=True, check=False, timeout=240,
        )
        self.assertEqual(0, result.returncode,
                         "Offline regressions failed:\n" + result.stderr[-1600:])


if __name__ == "__main__":
    unittest.main()
